// Builds api/_curriculum_index.js (server only) from data/curriculum-index.json.
//   node scripts/build-curriculum-index.js
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const data = JSON.parse(fs.readFileSync(path.join(root, 'data', 'curriculum-index.json'), 'utf8'));
fs.writeFileSync(path.join(root, 'api', '_curriculum_index.js'),
  '// GENERATED by scripts/build-curriculum-index.js from data/curriculum-index.json. Do not edit by hand.\n\'use strict\';\nmodule.exports = ' + JSON.stringify(data) + ';\n');
console.log('Wrote api/_curriculum_index.js with ' + data.count + ' indicators.');
